// R10 is a per-method text heuristic: it fires when `Expanded` and
// `SingleChildScrollView` appear anywhere in the same build method, even in
// branches that can never both render. Verify the tree, then confirm.
Widget build(BuildContext context) {
  if (lists.length > 4) {
    return SingleChildScrollView(      // no Expanded in this branch
      scrollDirection: Axis.horizontal,
      child: Row(children: [for (final l in lists) SizedBox(width: 84, ...)]),
    );
  }
  return Row(                          // bounded width, no scroll view
    children: [for (final l in lists) Expanded(child: _chip(l))],
  );
}

