-- Readable before sign-up, because that is when it is read.
create policy fields_read on public.fields
  for select to anon, authenticated using (true);

-- RLS filters rows; a missing GRANT fails the query outright. Both are needed.
grant select on public.fields         to anon, authenticated;
grant select on public.field_overview to anon, authenticated;

-- And never let a pre-auth screen REQUIRE data it may not be able to read:
// register: the field is optional, /choose-field enforces it after sign-in
context.read<RegisterCubit>().submit(..., fieldId: _field?.id);

-- The view filters itself by the caller, and every read inherits it —
-- favourites, lists, review, word-by-id, and anything written later.
create or replace function public.current_field_id()
returns text language sql stable security definer set search_path = public as $$
  select p.field_id from public.profiles p where p.id = auth.uid();
$$;
grant execute on function public.current_field_id() to anon, authenticated;

create or replace view public.word_overview
with (security_invoker = on) as
select ...                       -- column list UNCHANGED (see the other lesson)
from public.words w ...
where public.current_field_id() is null      -- no field = whole catalog
   or w.field_id = public.current_field_id();

